mapper.delete:
delete from ssm_hot_table_repair_task
where source_table_name in(

     #{item}

    )

mapper.select:
select t1.task_id as taskId, t1.source_table_name as sourceTableName, t1.task_start_date as taskStartDate, t1.task_end_date as taskEndDate, t1.task_batch_no as taskBatchNo, t1.task_script_type as taskScriptType, t1.task_script_content as taskScriptContent, if(t3.task_exec_status is null , 'ready', t3.task_exec_status) as taskExecStatus, t3.task_exec_info as taskExecInfo, date_format(t3.task_exec_start_time, '%Y-%m-%d %H:%i:%s') as taskExecStartTime, date_format(t3.task_exec_end_time, '%Y-%m-%d %H:%i:%s') as taskExecEndTime, t1.task_desc as taskDesc, t1.task_server_ip taskServerIp, t1.created_by as createdBy, date_format(t1.created_time, '%Y-%m-%d %H:%i:%s') as createdTime, t1.updated_by as updatedBy, date_format(t1.updated_time, '%Y-%m-%d %H:%i:%s') as updatedTime, t2.sla_priority, t3.task_exec_id as taskExecId, if(t3.data_check_result is null , 'ready',t3.data_check_result) as dataCheckResult, t3.data_check_info as dataCheckInfo, date_format(t3.data_check_time, '%Y-%m-%d %H:%i:%s') as dataCheckTime, t3.is_hot_min_date_updated as isHotMinDateUpdated from ssm_hot_table_repair_task t1 inner join ssm_hot_table_source t2 on t1.source_table_name = t2.source_table_name left join ssm_hot_table_repair_task_log t3 on t1.task_id = t3.task_id where 1=1 and t1.is_active = 1 and t2.is_active = 1 and t2.is_auto_repair_data = 1
and t1.source_table_name = #{sourceTableName}
and t1.task_id in(
#{item}
)
order by t2.sla_priority desc, t1.source_table_name, t1.task_start_date desc, t1.task_batch_no
